/**
 * Windows 98 Authentic Canvas Boot Screen & Palette Animation
 * Uses the original 320x400 8-bit indexed bitmap from LOGO.SYS
 * Replicates hardware palette cycling and stretches to authentic 4:3 (640x480) VGA display.
 */
(function () {
  const B64_DATA = "";

  class Win98BootScreen {
    constructor() {
      this.container = document.getElementById('win98-boot-screen');
      this.canvas = document.getElementById('win98-boot-canvas');
      this.skipBtn = document.getElementById('win98-boot-skip');
      this.ctx = this.canvas ? this.canvas.getContext('2d') : null;
      this.animId = null;
      this.isEnded = false;
      this.lastTick = 0;
      this.paletteCycleInterval = 45; // ~22Hz authentic palette shift rate

      if (!this.container || !this.canvas || !this.ctx) return;
      this.init();
    }

    init() {
      try {
        const binStr = atob(B64_DATA);
        const len = binStr.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binStr.charCodeAt(i);
        }
        this.bytes = bytes;

        // Parse 256-color palette (54 offset, BGR0)
        this.palette = [];
        for (let i = 0; i < 256; i++) {
          const off = 54 + i * 4;
          this.palette.push([bytes[off + 2], bytes[off + 1], bytes[off], 255]); // R, G, B, A
        }

        // Palette entries 236..255 (20 colors) animate in a loop
        this.animColors = [];
        for (let i = 236; i <= 255; i++) {
          this.animColors.push([...this.palette[i]]);
        }

        this.pixelOffset = 1078;
        this.srcWidth = 320;
        this.srcHeight = 400;

        // Display canvas set to authentic 4:3 CRT aspect ratio (640x480)
        this.width = 640;
        this.height = 480;
        this.canvas.width = this.width;
        this.canvas.height = this.height;

        // Offscreen 320x400 buffer for fast raw bitmap operations
        this.offscreenCanvas = document.createElement('canvas');
        this.offscreenCanvas.width = this.srcWidth;
        this.offscreenCanvas.height = this.srcHeight;
        this.offscreenCtx = this.offscreenCanvas.getContext('2d');
        this.offscreenImgData = this.offscreenCtx.createImageData(this.srcWidth, this.srcHeight);
        this.offscreenData32 = new Uint32Array(this.offscreenImgData.data.buffer);

        // Initial full screen draw (bottom-up BMP) to offscreen buffer
        for (let y = 0; y < this.srcHeight; y++) {
          const srcY = 399 - y;
          const rowSrc = this.pixelOffset + srcY * this.srcWidth;
          const rowDst = y * this.srcWidth;
          for (let x = 0; x < this.srcWidth; x++) {
            const colorIdx = this.bytes[rowSrc + x];
            const [r, g, b, a] = this.palette[colorIdx];
            this.offscreenData32[rowDst + x] = (a << 24) | (b << 16) | (g << 8) | r;
          }
        }
        this.offscreenCtx.putImageData(this.offscreenImgData, 0, 0);

        // Stretch to 640x480 on main display canvas with crisp pixels
        this.ctx.imageSmoothingEnabled = false;
        this.ctx.drawImage(this.offscreenCanvas, 0, 0, this.srcWidth, this.srcHeight, 0, 0, this.width, this.height);

        // Bind interactive skip
        if (this.skipBtn) {
          this.skipBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.end();
          });
        }
        this.container.addEventListener('click', () => this.end());
        window.addEventListener('keydown', (e) => {
          if (!this.isEnded) this.end();
        }, { once: true });

        // Start animation loop
        this.startLoop();
      } catch (err) {
        console.error('Failed to initialize Win98 boot screen:', err);
      }
    }

    startLoop() {
      const animate = (timestamp) => {
        if (this.isEnded) return;

        if (timestamp - this.lastTick >= this.paletteCycleInterval) {
          this.lastTick = timestamp;
          this.cyclePalette();
        }

        this.animId = requestAnimationFrame(animate);
      };
      this.animId = requestAnimationFrame(animate);
    }

    cyclePalette() {
      // Authentic palette rotation for colors 236..255
      const first = this.animColors.shift();
      this.animColors.push(first);
      for (let i = 0; i < 20; i++) {
        this.palette[236 + i] = this.animColors[i];
      }

      // Redraw only the bottom 7 animated rows (y = 393..399) in offscreen buffer
      for (let y = 393; y < 400; y++) {
        const srcY = 399 - y;
        const rowSrc = this.pixelOffset + srcY * this.srcWidth;
        const rowDst = y * this.srcWidth;
        for (let x = 0; x < this.srcWidth; x++) {
          const colorIdx = this.bytes[rowSrc + x];
          if (colorIdx >= 236) {
            const [r, g, b, a] = this.palette[colorIdx];
            this.offscreenData32[rowDst + x] = (a << 24) | (b << 16) | (g << 8) | r;
          }
        }
      }

      // Fast putImageData for the bottom 7 rows on offscreen buffer
      this.offscreenCtx.putImageData(this.offscreenImgData, 0, 0, 0, 393, 320, 7);

      // Blit bottom animated region stretched to 640x480 canvas (source y: 393..400 -> dest y: 471..480)
      this.ctx.imageSmoothingEnabled = false;
      this.ctx.drawImage(this.offscreenCanvas, 0, 393, 320, 7, 0, 471, 640, 9);
    }

    end() {
      if (this.isEnded) return;
      this.isEnded = true;

      if (this.animId) {
        cancelAnimationFrame(this.animId);
        this.animId = null;
      }

      if (this.container) {
        this.container.classList.add('fade-out');
        setTimeout(() => {
          this.container.style.display = 'none';
          if (window.onWin98BootFinished) {
            window.onWin98BootFinished();
          }
        }, 500);
      }
    }
  }

  window.Win98BootScreen = Win98BootScreen;
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      window.win98Boot = new Win98BootScreen();
    });
  } else {
    window.win98Boot = new Win98BootScreen();
  }
})();
